insert into kafaa_benchmark_values (id, benchmark_id, figure_key, metric, label_en, label_ar, value, unit, scale_max, as_of, source_url, verification, shown, held_reason_en, held_reason_ar, pack_ref, compare_to, dashboards, note_en, note_ar, sort) values
('bv-ssg-sf-ai-aided-tasks', 'SSG-SF', 'ai_aided_tasks', 'ai_task_share', 'Tasks that AI can significantly aid', 'المهام التي يمكن للذكاء الاصطناعي أن يساعد فيها بدرجة كبيرة', 24, 'pct', 100, '2026-10-10', 'https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf', 'primary', true, '', '', 'research/national_systems.md §1.2 (SSG Factsheet 2, primary PDF verified by direct download)', 'ai_task_share', array['skills_outlook','overview']::text[], 'Singapore, about 37,000 key work tasks scored for AI potential. Its method differs from the FS06 exposure rule (augment or partly automatable): read it as context, not a target.', 'سنغافورة، نحو 37,000 مهمة عمل رئيسية قُيّمت لإمكانات الذكاء الاصطناعي. تختلف منهجيتها عن قاعدة التعرّض في FS06 (تعزيز أو أتمتة جزئية): اقرأها سياقاً لا هدفاً.', 10),
('bv-forecast-priority-demand-growth-2030', 'FORECAST', 'priority_demand_growth_2030', 'demand_growth_2030', 'Priority-occupation demand growth to 2030', 'نمو الطلب على المهن ذات الأولوية حتى 2030', 15, 'pct', 100, '2026-10-10', 'https://www.gov.uk/government/publications/assessment-of-priority-skills-to-2030/assessment-of-priority-skills-to-2030', 'primary', true, '', '', 'research/national_systems.md §3.1 (Skills England, primary, read directly from the report)', 'demand_growth_2030', array['skills_outlook','overview']::text[], 'United Kingdom, priority-occupation employment 2025 to 2030 across ten sectors. ENEC''s figure is SIMULATED demand for skill families 2026 to 2030: context, not a like-for-like comparison.', 'المملكة المتحدة، التوظيف في المهن ذات الأولوية من 2025 إلى 2030 في عشرة قطاعات. رقم مؤسسة الإمارات للطاقة النووية طلب محاكى لفئات المهارات من 2026 إلى 2030: سياق وليس مقارنة مباشرة.', 20),
('bv-digcomp-above-basic-eu-2023', 'DIGCOMP', 'above_basic_eu_2023', 'digital_above_basic', 'EU adults with above-basic digital skills (2023)', 'البالغون في الاتحاد الأوروبي بمهارات رقمية فوق الأساسية (2023)', 56, 'pct', 100, '2026-10-10', 'https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en', 'primary', true, '', '', 'research/global_frameworks.md §9 (JRC DigComp page, read directly 2026-10-10)', 'digital_holders', array['skills_outlook','overview']::text[], 'All EU adults with above-basic digital skills (2023). ENEC''s figure is staff at Practitioner level or above in the digital skill family, a higher bar: read it as context.', 'جميع البالغين في الاتحاد الأوروبي ممن لديهم مهارات رقمية فوق الأساسية (2023). رقم المؤسسة هو الموظفون بمستوى ممارس فأعلى في فئة المهارات الرقمية، وهو معيار أعلى: اقرأه سياقاً.', 30),
('bv-uk-nuc-new-jobs-2030', 'UK-NUC', 'new_jobs_2030', 'new_nuclear_jobs_2030', 'New nuclear jobs by 2030', 'وظائف نووية جديدة بحلول 2030', 40000, 'count', null, '2026-10-10', 'https://world-nuclear-news.org/articles/uk-sets-out-plan-for-boosting-nuclear-workforce', 'primary', true, '', '', 'research/nuclear_energy.md §9 (World Nuclear News, verified: curl 2026-10-10)', null, array['skills_outlook']::text[], 'A national sector target for the United Kingdom, shown as market context only; it is not compared with any ENEC number.', 'هدف قطاعي وطني في المملكة المتحدة، يُعرض سياقاً للسوق فقط ولا يُقارن بأي رقم للمؤسسة.', 40),
('bv-wef-foj-core-skills-change-2030', 'WEF-FOJ', 'core_skills_change_2030', 'core_skills_change_2030', 'Workers'' core skills expected to change by 2030', 'المهارات الأساسية للعاملين المتوقع تغيّرها بحلول 2030', 39, 'pct', 100, '2026-10-10', 'https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/', 'secondary', false, 'Held back: the research pack corroborates this figure from secondary reports only (weforum.org could not be read). It returns once someone reads the WEF page itself.', 'محجوب: يؤكد ملف البحث هذا الرقم من تقارير ثانوية فقط (تعذّرت قراءة موقع المنتدى). يعود بعد قراءة صفحة المنتدى نفسها.', 'research/global_frameworks.md §1 [WEF-secondary]: weforum.org was blocked from the research container', null, '{}'::text[], '', '', 50),
('bv-energy-jobs-firms-reporting-shortages', 'ENERGY-JOBS', 'firms_reporting_shortages', 'firms_reporting_shortages', 'Surveyed firms reporting shortages', 'الشركات المشمولة التي أفادت بنقص', 60, 'pct', 100, '2026-10-10', 'https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025', 'secondary', false, 'Held back: the research pack takes the IEA survey result from trade press [secondary]. It returns once the IEA report itself is read.', 'محجوب: يأخذ ملف البحث نتيجة مسح الوكالة الدولية للطاقة من الصحافة المتخصصة [ثانوي]. يعود بعد قراءة تقرير الوكالة نفسه.', 'research/nuclear_energy.md §16 [secondary]: trade-press reports of the IEA survey', null, '{}'::text[], '', '', 60),
('bv-energy-jobs-energy-jobs-2024', 'ENERGY-JOBS', 'energy_jobs_2024', 'energy_jobs', 'Energy jobs worldwide (2024)', 'وظائف الطاقة في العالم (2024)', 76000000, 'count', null, '2026-10-10', 'https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025', 'secondary', false, 'Held back: secondary in the research pack (trade-press summary of the IEA report).', 'محجوب: ثانوي في ملف البحث (ملخص صحفي لتقرير الوكالة الدولية للطاقة).', 'research/nuclear_energy.md §16 [secondary]: trade-press reports of World Energy Employment 2025', null, '{}'::text[], '', '', 70),
('bv-eu-pact-people-trained', 'EU-PACT', 'people_trained', 'people_trained', 'People trained (cumulative, 2025)', 'الأشخاص المدرَّبون (تراكمياً، 2025)', 10000000, 'count', null, '2026-10-10', 'https://pact-for-skills.ec.europa.eu/about/news-and-factsheets/more-61-million-workers-trained-under-pact-skills-2025-05-19_en', 'secondary', false, 'Held back: the linked Commission page reports the 2024 survey; the cumulative 2025 total comes from secondary sites. It returns once the Commission publishes it.', 'محجوب: صفحة المفوضية المرتبطة تعرض مسح 2024؛ أما إجمالي 2025 التراكمي فمصدره مواقع ثانوية. يعود بعد نشر المفوضية له.', 'research/global_frameworks.md §7: the 2025 total is reported by euricse.eu and cepis.org; the Commission page linked reports the 2024 survey', null, '{}'::text[], '', '', 80),
('bv-smr-wf-hires-2023-2033', 'SMR-WF', 'hires_2023_2033', 'sector_hires', 'Hires in France 2023-2033 (MATCH)', 'التعيينات في فرنسا 2023-2033 (MATCH)', 100000, 'count', null, '2026-10-10', 'https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/', 'secondary', false, 'Held back: secondary in the research pack (MATCH programme summaries).', 'محجوب: ثانوي في ملف البحث (ملخصات برنامج MATCH).', 'research/nuclear_energy.md §11 [secondary]: MATCH figures from GIFEN/EDF summaries', null, '{}'::text[], '', '', 90),
('bv-uae-peers-staff-trained-ai', 'UAE-PEERS', 'staff_trained_ai', 'peer_ai_trained', 'ADNOC staff trained on AI fundamentals', 'موظفو أدنوك المدرَّبون على أساسيات الذكاء الاصطناعي', 40000, 'count', null, '2026-10-10', 'https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42', 'secondary', false, 'Held back: company-reported and tagged secondary [S] in the research pack.', 'محجوب: رقم أعلنته الشركة ومصنّف ثانوياً [S] في ملف البحث.', 'research/corporate_platforms.md A11 [S, company-reported]', null, '{}'::text[], '', '', 100)
